import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import { t } from '../../common/t';
import { when } from '../labels';
import OddsButton from './OddsButton';
const ROWS = ['away', 'home'];

/**
 * A game the way every book shows one: two rows, the sides, and a column per
 * market. Anything else (a draw, props) is on the event's own page.
 */
export default class EventCard extends Component {
  view() {
    const event = this.attrs.event;
    const markets = event.markets ?? [];
    const scored = ['spread', 'total', 'moneyline'].map(type => markets.find(mk => mk.type === type));
    const extra = markets.filter(mk => mk.type === 'custom').length + (markets.some(mk => mk.selections.some(s => s.key === 'draw')) ? 1 : 0);
    return m("article", {
      className: "Longshot-event"
    }, m("header", {
      className: "Longshot-event-head"
    }, m("span", {
      className: "Longshot-event-league"
    }, event.league), this.status(event), m(Link, {
      className: "Longshot-event-more",
      href: app.route('longshot.event', {
        id: event.id
      })
    }, extra ? t('forum.board.more_markets', {
      count: extra
    }) : t('forum.board.details'), event.offers ? m("span", {
      className: "Longshot-badge"
    }, t('forum.board.offers', {
      count: event.offers
    })) : null)), event.home && event.away ? m("div", {
      className: "Longshot-grid",
      role: "table",
      "aria-label": event.name
    }, m("div", {
      className: "Longshot-grid-row Longshot-grid-labels",
      role: "row"
    }, m("span", {
      role: "columnheader"
    }), scored.map((mk, i) => m("span", {
      role: "columnheader",
      key: i
    }, mk ? t('forum.market.' + mk.type) : ''))), ROWS.map(side => m("div", {
      className: "Longshot-grid-row",
      role: "row",
      key: side
    }, m("span", {
      className: "Longshot-team",
      role: "rowheader"
    }, event[side]?.logo ? m("img", {
      src: event[side].logo,
      alt: "",
      width: "24",
      height: "24",
      loading: "lazy",
      decoding: "async"
    }) : null, m("span", {
      className: "Longshot-team-name"
    }, event[side]?.name), event.score ? m("strong", {
      className: "Longshot-team-score"
    }, event.score[side]) : null), scored.map((mk, i) => m("span", {
      role: "cell",
      key: i
    }, this.cell(event, mk, side)))))) : m("div", {
      className: "Longshot-titled"
    }, m("h3", null, event.title), markets.slice(0, 1).map(mk => m("div", {
      className: "Longshot-options"
    }, mk.selections.slice(0, 6).map(s => m(OddsButton, {
      event: event,
      market: mk,
      selection: s,
      named: true
    }))))));
  }
  cell(event, market, side) {
    if (!market) return null;
    const key = market.type === 'total' ? side === 'away' ? 'over' : 'under' : side;
    const selection = market.selections.find(s => s.key === key);
    return selection ? m(OddsButton, {
      event: event,
      market: market,
      selection: selection
    }) : null;
  }
  status(event) {
    if (event.status === 'void') return m("span", {
      className: "Longshot-state is-void"
    }, t('forum.event.void'));
    if (event.status === 'settled') return m("span", {
      className: "Longshot-state is-final"
    }, t('forum.event.final'));
    if (!event.bettable) {
      return m("span", {
        className: "Longshot-state is-live"
      }, m(Icon, {
        name: "fas fa-circle"
      }), " ", t('forum.event.started'));
    }
    return m("time", {
      className: "Longshot-state",
      dateTime: event.startsAt
    }, when(event.startsAt));
  }
}
flarum.reg.add('ernestdefoe-longshot', 'forum/components/EventCard', EventCard);